CREATE SCHEMA IF NOT EXISTS ${schema};
CREATE TABLE ${schema}.errors (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,error_code text NOT NULL UNIQUE,technical_category text NOT NULL,http_status integer NOT NULL CHECK(http_status BETWEEN 400 AND 599),user_title text,user_message text,suggested_action text,copy_status text NOT NULL DEFAULT 'PENDING_COPY' CHECK(copy_status IN ('PENDING_COPY','APPROVED')),is_active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(copy_status <> 'APPROVED' OR (nullif(btrim(user_title),'') IS NOT NULL AND nullif(btrim(user_message),'') IS NOT NULL)));
COMMENT ON TABLE ${schema}.errors IS 'mutable';
CREATE TABLE ${schema}.error_occurrences(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,error_id bigint NOT NULL REFERENCES ${schema}.errors(id),trace_code text NOT NULL UNIQUE CHECK(trace_code ~ '^${trace_prefix}-[0-9]{8}-[A-Z0-9]{8}$'),correlation_id uuid NOT NULL,request_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),context jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(context)='object'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.error_occurrences IS 'append-only';
CREATE INDEX ON ${schema}.error_occurrences(correlation_id);
CREATE TABLE ${schema}.messages(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,message_code text NOT NULL UNIQUE,title text,message_text text,suggested_action text,action_label text,reference_label text,copy_status text NOT NULL DEFAULT 'PENDING_COPY' CHECK(copy_status IN ('PENDING_COPY','APPROVED')),is_active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.messages IS 'mutable';
CREATE TABLE ${schema}.audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,occurred_at timestamptz NOT NULL DEFAULT now(),actor_ref text,action_code text NOT NULL,entity_type text NOT NULL,entity_ref text,result_code text NOT NULL,correlation_id uuid NOT NULL,trace_code text,details jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(details)='object'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.audit_events IS 'append-only';
CREATE INDEX ON ${schema}.audit_events(correlation_id,occurred_at);
CREATE TABLE ${schema}.navigation_event_types(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_code text NOT NULL UNIQUE,event_category text NOT NULL CHECK(event_category IN ('screen_view','action','submit','error','exit')),description text,is_active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.navigation_event_types IS 'mutable';
CREATE TABLE ${schema}.navigation_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,session_id uuid NOT NULL,user_ref text,screen_code text NOT NULL,event_type_id bigint NOT NULL REFERENCES ${schema}.navigation_event_types(id),occurred_at timestamptz NOT NULL,duration_ms bigint CHECK(duration_ms IS NULL OR duration_ms >= 0),trace_code text,correlation_id uuid NOT NULL,channel text,device_type text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.navigation_events IS 'append-only';
CREATE INDEX ON ${schema}.navigation_events(session_id,occurred_at DESC,id DESC);
CREATE INDEX ON ${schema}.navigation_events(trace_code,occurred_at);
CREATE TABLE ${schema}.legal_documents(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,document_type text NOT NULL,document_version text NOT NULL,content_sha256 char(64) NOT NULL CHECK(content_sha256 ~ '^[0-9a-f]{64}$'),valid_from timestamptz NOT NULL,valid_to timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_type,document_version),CHECK(valid_to IS NULL OR valid_to > valid_from));
COMMENT ON TABLE ${schema}.legal_documents IS 'controlled-validity';
CREATE TABLE ${schema}.consents(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_ref text NOT NULL,legal_document_id bigint NOT NULL REFERENCES ${schema}.legal_documents(id),consent_type text NOT NULL,is_granted boolean NOT NULL,occurred_at timestamptz NOT NULL,ip_address inet,browser_info text,channel text,screen_code text,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
COMMENT ON TABLE ${schema}.consents IS 'append-only';
CREATE INDEX ON ${schema}.consents(user_ref,consent_type,occurred_at DESC,id DESC);
REVOKE ALL ON ALL TABLES IN SCHEMA ${schema} FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA ${schema} FROM PUBLIC;
